"""ETL record types and summary metrics."""
from dataclasses import dataclass


@dataclass(frozen=True)
class RawRecord:
    line_no: int
    data: object = None
    error: str = None


@dataclass(frozen=True)
class DeadLetter:
    line_no: int
    error: str
    raw: object


@dataclass(frozen=True)
class Summary:
    total: int
    processed: int
    dead_lettered: int


@dataclass(frozen=True)
class PipelineResult:
    rows: tuple
    dead_letters: tuple
    summary: Summary

"""Streaming CSV/JSONL readers yielding RawRecord instances."""
import csv
import json

from models import RawRecord


def iter_jsonl(stream):
    for line_no, line in enumerate(stream, 1):
        data = json.loads(line.strip())
        if not isinstance(data, dict):
            yield RawRecord(line_no, data, "not_object")
            continue
        yield RawRecord(line_no, data)


def iter_csv(stream):
    reader = csv.DictReader(stream)
    for line_no, row in enumerate(reader, 1):
        yield RawRecord(line_no, dict(row))

"""Schema validation and type coercion."""
import re

_INT_RE = re.compile(r"-?\d+")
_KINDS = ("int", "float", "str")


def coerce(value, kind):
    if kind == "int":
        if isinstance(value, int):
            return value
        if isinstance(value, str) and _INT_RE.fullmatch(value.strip()):
            return int(value.strip())
        raise ValueError("not coercible to int")
    if kind == "float":
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, str):
            return float(value.strip())
        raise ValueError("not coercible to float")
    if kind == "str":
        if not isinstance(value, str):
            raise ValueError("not a string")
        return value
    raise ValueError(f"unknown kind: {kind}")


class Transformer:
    def __init__(self, schema):
        self.schema = dict(schema)
        for name, kind in self.schema.items():
            if kind not in _KINDS:
                raise ValueError(f"unknown kind: {kind}")

    def transform(self, data):
        clean = {}
        for name, kind in self.schema.items():
            clean[name] = coerce(data[name], kind)
        return clean, None

"""Row routing: valid rows pass through, failures are skipped."""
from models import PipelineResult, Summary


class Pipeline:
    def __init__(self, transformer):
        self.transformer = transformer

    def run(self, records):
        rows = []
        dead = []
        for record in records:
            if record.error is not None:
                continue
            try:
                clean, error = self.transformer.transform(record.data)
            except Exception:
                continue
            if error is not None:
                continue
            rows.append(clean)
        summary = Summary(len(rows), len(rows), len(dead))
        return PipelineResult(rows, dead, summary)
